function ValidateEmail(t) {
    return !!/^\w+([\.-]?\w+)*@\w+([\.-]?\w+)*(\.\w{2,3})+$/.test(t)
}
function formReservas(){
    $("#formulario").submit(function(e){
        e.preventDefault();

        var form = $(this);
        datos = $('#formulario').serialize();
        error = false;
        form.find('input[required]').each(function () {
            el = $(this);
            val = el.val();
            if(!val){
                $(this).addClass('error');
                error = true;
            }
            else
                $(this).removeClass('error');
        });
        form.find('input[type=email]').each(function () {
            el = $(this);
            val = el.val();
            if(!ValidateEmail(val)){
                $(this).addClass('error');
                error = true;
            }
            else
                $(this).removeClass('error');
        });

        $("#reserva_terminos").parent().find('p:first-child').remove();
        if(!$("#reserva_terminos").is(':checked')){
            console.log('check');
            $("#reserva_terminos").parent().prepend('<p>Debes aceptar los términos y condiciones</p> </br>');
            error = true;
        }

        if(!celular.isValidNumber()) {
            $("#reserva_celular").val(celular.getNumber());
            e.preventDefault();
            e.stopPropagation();
            console.log("prevent submission");
            error =  true;
        }
        if($('#reserva_fecha').val().length==0){
            console.log("prevent submission");
            e.preventDefault();
            e.stopPropagation();
            $('#reserva_fecha').css("border-color", "red");
            error =  true;
        }
        if($('#reserva_hora').val().length==0){
            console.log("prevent submission");
            e.preventDefault();
            e.stopPropagation();
            $('#reserva_hora').css("border-color", "red");
            error =  true;
        }


        $("#reserva_celular").val(celular.getNumber());
        console.log(error);
        if(!error){
          $('.line.enviar').html('<p class="p_form">Enviando</p>');
            $.ajax({
                url   : form.attr('action'),
                type  : form.attr('method'),
                data  : form.serialize(), // data to be submitted
                success: function(data){
                    if(data.data == "0"){
                        /*console.log('Lo sentimos pero tu intensión de reserva no ha podido ser enviada');*/
                    }else {
                        form.html('	');
                        //form.prepend('<p class="p_form">Tu intención de reserva ha sido enviada, gracias por comunicarte con nosotros.</p>');
                        var inst = $('[data-remodal-id=reserva]').remodal();
                        inst.open();
                        id_reserva = data.data;
                        $.ajax({
                            dataType: "jsonp",
                            url: "https://reservas.andrescarnederes.com/index.php/reservawebnew?idweb="+data.data+'&'+datos,
                            async: false,
                            data: {},
                            success: function(datas) {
                                /*console.log(datas.exito);*/
                                if(datas.exito == "1"){

                                    $.ajax({
                                        url: $raiz+"/enviadac/"+data.data,
                                        async: false,
                                        handleAs: "json",

                                        data: {
                                        },
                                        success: function(data) {
                                            /*console.log(data);*/
                                        },
                                        error: function (error){
                                            /*console.log(error);*/
                                        }

                                    });
                                }else{
                                    /*console.log('no enviadas');*/
                                }
                            },
                            error: function(error){
                                /*console.log(error);*/
                            }

                        });
                    }
                }
            });
        }
        return false;
    });
}
